def signature_key(sig: list[float]) -> str:
    return json.dumps(sig, sort_keys=True, separators=(",", ":"))


def quotient(rows: list[dict[str, Any]], probes: list[dict[str, Any]], name: str) -> dict[str, Any]:
    table = expectation_table(rows, probes) if probes else [[] for _ in rows]
    classes: dict[str, dict[str, Any]] = {}
    for row, sig in zip(rows, table, strict=True):
        key = signature_key(sig)
        classes.setdefault(key, {"members": [], "signature": sig})
        classes[key]["members"].append(row["id"])
    ordered = [
        {"class_id": f"{name}_q{idx}", "members": sorted(classes[key]["members"]), "signature": classes[key]["signature"]}
        for idx, key in enumerate(sorted(classes))
    ]
    return {"name": name, "probe_names": [probe["name"] for probe in probes], "class_count": len(ordered), "classes": ordered}


def relation_from_table(table: list[list[float]]) -> list[list[bool]]:
    return [[table[i] == table[j] for j in range(len(table))] for i in range(len(table))]


def relation_report(rel: list[list[bool]]) -> dict[str, bool]:
    n = len(rel)
    reflexive = all(rel[i][i] for i in range(n))
    symmetric = all((not rel[i][j]) or rel[j][i] for i in range(n) for j in range(n))
    transitive = all((not rel[i][j]) or (not rel[j][k]) or rel[i][k] for i in range(n) for j in range(n) for k in range(n))
    return {"reflexive": reflexive, "symmetric": symmetric, "transitive": transitive, "is_equivalence_relation": reflexive and symmetric and transitive}


def stability_report(base_rel: list[list[bool]], image_rel: list[list[bool]], ids: list[str]) -> dict[str, Any]:
    violating = [
        {"left": ids[i], "right": ids[j]}
        for i in range(len(ids))
        for j in range(len(ids))
        if base_rel[i][j] and not image_rel[i][j]
    ]
    return {"stable": not violating, "violating_pairs": violating}


def constraints_report(rows: list[dict[str, Any]], probes: list[dict[str, Any]]) -> dict[str, Any]:
    details = []
    for row in rows:
        rho = row["rho"]
        eigs = jnp.linalg.eigvalsh((rho + jnp.conj(rho.T)) / 2.0)
        details.append(
            {
                "id": row["id"],
                "trace_residual": py_float(jnp.abs(jnp.trace(rho) - 1.0)),
                "hermitian_residual": py_float(jnp.linalg.norm(rho - jnp.conj(rho.T))),
                "min_eigenvalue": py_float(jnp.min(eigs)),
                "active_expectations": [expectation(rho, probe["effect"]) for probe in probes],
                "psd": py_float(jnp.min(eigs)) >= -TOL,
            }
        )
    return {
        "trace_one": all(row["trace_residual"] <= TOL for row in details),
        "hermitian": all(row["hermitian_residual"] <= TOL for row in details),
        "psd": all(row["psd"] for row in details),
        "details": details,
    }


def unitary_residual(unitary: jax.Array) -> float:
    return py_float(jnp.linalg.norm(jnp.conj(unitary.T) @ unitary - I2))


def state_components(row: dict[str, Any]) -> dict[str, float]:
    rho = row["rho"]
    return {
        "rho00_re": rounded(jnp.real(rho[0, 0])),
        "rho11_re": rounded(jnp.real(rho[1, 1])),
        "rho01_re": rounded(jnp.real(rho[0, 1])),
        "rho01_im": rounded(jnp.imag(rho[0, 1])),
    }


def z3_real_value(value: float) -> z3.RatNumRef:
    f = frac(value)
    return z3.RealVal(f"{f.numerator}/{f.denominator}")


def z3_sum(terms: list[z3.ArithRef]) -> z3.ArithRef:
    return z3.RealVal(0) if not terms else sum(terms, z3.RealVal(0))


def z3_and(terms: list[z3.BoolRef]) -> z3.BoolRef:
    return z3.BoolVal(True) if not terms else z3.And(*terms)


def z3_or(terms: list[z3.BoolRef]) -> z3.BoolRef:
    return z3.BoolVal(False) if not terms else z3.Or(*terms)


def z3_bound_real(name: str, value: float) -> tuple[z3.ArithRef, z3.BoolRef]:
    var = z3.Real(name)
    return var, var == z3_real_value(value)


def z3_state_vars(row: dict[str, Any], idx: int) -> tuple[dict[str, z3.ArithRef], list[z3.BoolRef], int, int]:
    comps = state_components(row)
    vars_: dict[str, z3.ArithRef] = {}
    binds: list[z3.BoolRef] = []
    for key, value in comps.items():
        vars_[key], bind = z3_bound_real(f"rho_{idx}_{key}", value)
        binds.append(bind)
    a = vars_["rho00_re"]
    b = vars_["rho11_re"]
    c = vars_["rho01_re"]
    d = vars_["rho01_im"]
    constraints = [
        a >= 0,
        b >= 0,
        a + b == 1,
        a * b - c * c - d * d >= 0,
    ]
    return vars_, binds + constraints, len(binds), len(constraints)


def z3_state_matrix(vars_: dict[str, z3.ArithRef]) -> tuple[list[list[z3.ArithRef]], list[list[z3.ArithRef]]]:
    a = vars_["rho00_re"]
    b = vars_["rho11_re"]
    c = vars_["rho01_re"]
    d = vars_["rho01_im"]
    zero = z3.RealVal(0)
    return [[a, c], [c, b]], [[zero, d], [-d, zero]]


def z3_effect_vars(name: str, effect: dict[str, Any]) -> tuple[dict[str, list[list[z3.ArithRef]]], list[z3.BoolRef], int]:
    real: list[list[z3.ArithRef]] = []
    imag: list[list[z3.ArithRef]] = []
    constraints: list[z3.BoolRef] = []
    for i in range(2):
        real_row = []
        imag_row = []
        for j in range(2):
            r, rb = z3_bound_real(f"{name}_real_{i}_{j}", float(effect["real"][i][j]))
            im, ib = z3_bound_real(f"{name}_imag_{i}_{j}", float(effect["imag"][i][j]))
            real_row.append(r)
            imag_row.append(im)
            constraints.extend([rb, ib])
        real.append(real_row)
        imag.append(imag_row)
    return {"real": real, "imag": imag}, constraints, len(constraints)


def z3_trace_effect(state: dict[str, z3.ArithRef], effect: dict[str, list[list[z3.ArithRef]]]) -> z3.ArithRef:
    rho_r, rho_i = z3_state_matrix(state)
    terms: list[z3.ArithRef] = []
    for p in range(2):
        for q in range(2):
            er = effect["real"][p][q]
            ei = effect["imag"][p][q]
            rr = rho_r[q][p]
            ri = rho_i[q][p]
            terms.append(er * rr - ei * ri)
    return z3_sum(terms)


def z3_rel(expectations: list[list[z3.ArithRef]], i: int, j: int) -> z3.BoolRef:
    return z3_and([expectations[i][m] == expectations[j][m] for m in range(len(expectations[i]))])


def z3_model_text(model: z3.ModelRef, expr: z3.ExprRef) -> str:
    return str(model.evaluate(expr, model_completion=True))


def z3_matrix_entry_check(
    *,
    image_effect: dict[str, Any],
    include_stability_constraint: bool,
    include_transitivity_violation: bool,
    include_stability_violation: bool,
    rows: list[dict[str, Any]],
    ids: list[str],
    prefix: str,
) -> dict[str, Any]:
    solver = z3.Solver()
    state_vars = []
    constraints: list[z3.BoolRef] = []
    matrix_bind_count = 0
    state_constraint_count = 0
    for idx, row in enumerate(rows):
        vars_, row_constraints, row_binds, row_state_constraints = z3_state_vars(row, idx)
        state_vars.append(vars_)
        constraints.extend(row_constraints)
        matrix_bind_count += row_binds
        state_constraint_count += row_state_constraints
    active_effect, active_constraints, active_bind_count = z3_effect_vars(f"{prefix}_active_probe", ACTIVE_EFFECT)
    post_effect, post_constraints, post_bind_count = z3_effect_vars(f"{prefix}_post_probe", image_effect)
    constraints.extend(active_constraints + post_constraints)
    matrix_bind_count += active_bind_count + post_bind_count

    base_expectations = [[z3_trace_effect(state, active_effect)] for state in state_vars]
    post_expectations = [[z3_trace_effect(state, post_effect)] for state in state_vars]
    stability_implications = [z3.Implies(z3_rel(base_expectations, i, j), z3_rel(post_expectations, i, j)) for i in range(len(rows)) for j in range(len(rows))]
    if include_stability_constraint:
        constraints.extend(stability_implications)

    transitivity_terms = [
        z3.And(
            z3_rel(base_expectations, i, j),
            z3_rel(base_expectations, j, k),
            z3.Not(z3_rel(base_expectations, i, k)),
        )
        for i in range(len(rows))
        for j in range(len(rows))
        for k in range(len(rows))
    ]
    stability_terms = [
        z3.And(z3_rel(base_expectations, i, j), z3.Not(z3_rel(post_expectations, i, j)))
        for i in range(len(rows))
        for j in range(len(rows))
    ]
    violation_terms: list[z3.BoolRef] = []
    if include_transitivity_violation:
        violation_terms.extend(transitivity_terms)
    if include_stability_violation:
        violation_terms.extend(stability_terms)

    solver.add(*constraints)
    solver.add(z3_or(violation_terms))
    verdict = str(solver.check())
    witness = None
    if verdict == "sat":
        model = solver.model()
        for idx, term in enumerate(stability_terms):
            if z3.is_true(model.evaluate(term, model_completion=True)):
                i, j = divmod(idx, len(rows))
                witness = {
                    "kind": "base-equivalent pair splits under post-effect",
                    "indices": [i, j],
                    "ids": [ids[i], ids[j]],
                    "base_expectations": [z3_model_text(model, base_expectations[i][0]), z3_model_text(model, base_expectations[j][0])],
                    "post_expectations": [z3_model_text(model, post_expectations[i][0]), z3_model_text(model, post_expectations[j][0])],
                }
                break

    return {
        "verdict": verdict,
        "witness": witness,
        "asserted_matrix_entry_equalities": matrix_bind_count,
        "state_constraint_terms": state_constraint_count,
        "stability_implications": len(stability_implications) if include_stability_constraint else 0,
        "derived_trace_terms": len(base_expectations) + len(post_expectations),
        "transitivity_violation_terms": len(transitivity_terms) if include_transitivity_violation else 0,
        "stability_violation_terms": len(stability_terms) if include_stability_violation else 0,
    }


def cvc5_real_value(solver: cvc5.Solver, value: float) -> Any:
    f = frac(value)
    return solver.mkReal(f.numerator, f.denominator)


def cvc5_sum(solver: cvc5.Solver, terms: list[Any]) -> Any:
    if not terms:
        return solver.mkReal(0)
    return terms[0] if len(terms) == 1 else solver.mkTerm(cvc5.Kind.ADD, *terms)


def cvc5_sub(solver: cvc5.Solver, left: Any, right: Any) -> Any:
    return solver.mkTerm(cvc5.Kind.SUB, left, right)


def cvc5_mul(solver: cvc5.Solver, *terms: Any) -> Any:
    return terms[0] if len(terms) == 1 else solver.mkTerm(cvc5.Kind.MULT, *terms)


def cvc5_and(solver: cvc5.Solver, terms: list[Any]) -> Any:
    if not terms:
        return solver.mkBoolean(True)
    return terms[0] if len(terms) == 1 else solver.mkTerm(cvc5.Kind.AND, *terms)


def cvc5_or(solver: cvc5.Solver, terms: list[Any]) -> Any:
    if not terms:
        return solver.mkBoolean(False)
    return terms[0] if len(terms) == 1 else solver.mkTerm(cvc5.Kind.OR, *terms)


def cvc5_not(solver: cvc5.Solver, term: Any) -> Any:
    return solver.mkTerm(cvc5.Kind.NOT, term)


def cvc5_eq(solver: cvc5.Solver, left: Any, right: Any) -> Any:
    return solver.mkTerm(cvc5.Kind.EQUAL, left, right)


def cvc5_geq(solver: cvc5.Solver, left: Any, right: Any) -> Any:
    return solver.mkTerm(cvc5.Kind.GEQ, left, right)


def cvc5_bound_real(solver: cvc5.Solver, real_sort: Any, name: str, value: float) -> tuple[Any, Any]:
    var = solver.mkConst(real_sort, name)
    return var, cvc5_eq(solver, var, cvc5_real_value(solver, value))


def cvc5_state_vars(solver: cvc5.Solver, real_sort: Any, row: dict[str, Any], idx: int) -> tuple[dict[str, Any], list[Any], int, int]:
    comps = state_components(row)
    vars_: dict[str, Any] = {}
    binds: list[Any] = []
    for key, value in comps.items():
        vars_[key], bind = cvc5_bound_real(solver, real_sort, f"rho_{idx}_{key}", value)
        binds.append(bind)
    a = vars_["rho00_re"]
    b = vars_["rho11_re"]
    c = vars_["rho01_re"]
    d = vars_["rho01_im"]
    zero = solver.mkReal(0)
    det = cvc5_sub(solver, cvc5_sub(solver, cvc5_mul(solver, a, b), cvc5_mul(solver, c, c)), cvc5_mul(solver, d, d))
    constraints = [
        cvc5_geq(solver, a, zero),
        cvc5_geq(solver, b, zero),
        cvc5_eq(solver, solver.mkTerm(cvc5.Kind.ADD, a, b), solver.mkReal(1)),
        cvc5_geq(solver, det, zero),
    ]
    return vars_, binds + constraints, len(binds), len(constraints)


def cvc5_state_matrix(solver: cvc5.Solver, vars_: dict[str, Any]) -> tuple[list[list[Any]], list[list[Any]]]:
    a = vars_["rho00_re"]
    b = vars_["rho11_re"]
    c = vars_["rho01_re"]
    d = vars_["rho01_im"]
    zero = solver.mkReal(0)
    return [[a, c], [c, b]], [[zero, d], [cvc5_sub(solver, zero, d), zero]]


def cvc5_effect_vars(solver: cvc5.Solver, real_sort: Any, name: str, effect: dict[str, Any]) -> tuple[dict[str, list[list[Any]]], list[Any], int]:
    real: list[list[Any]] = []
    imag: list[list[Any]] = []
    constraints: list[Any] = []
    for i in range(2):
        real_row = []
        imag_row = []
        for j in range(2):
            r, rb = cvc5_bound_real(solver, real_sort, f"{name}_real_{i}_{j}", float(effect["real"][i][j]))
            im, ib = cvc5_bound_real(solver, real_sort, f"{name}_imag_{i}_{j}", float(effect["imag"][i][j]))
            real_row.append(r)
            imag_row.append(im)
            constraints.extend([rb, ib])
        real.append(real_row)
        imag.append(imag_row)
    return {"real": real, "imag": imag}, constraints, len(constraints)


def cvc5_trace_effect(solver: cvc5.Solver, state: dict[str, Any], effect: dict[str, list[list[Any]]]) -> Any:
    rho_r, rho_i = cvc5_state_matrix(solver, state)
    terms: list[Any] = []
    for p in range(2):
